def transform(grid):
    h, w = len(grid), len(grid[0])

    # The repeated tile border is the most frequent nonzero color.
    freq = {}
    for row in grid:
        for value in row:
            if value:
                freq[value] = freq.get(value, 0) + 1
    border = max(freq, key=freq.get)

    # Find connected colored patches, excluding the tile border.
    seen = set()
    patches = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == border or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            patches.append((
                color,
                min(y for y, x in cells), max(y for y, x in cells),
                min(x for y, x in cells), max(x for y, x in cells),
                len(cells)
            ))

    # The most common interior patch color is the ordinary tile content;
    # connect only the exceptional colors.
    totals = {}
    for color, r0, r1, c0, c1, area in patches:
        totals[color] = totals.get(color, 0) + area
    ordinary = max(totals, key=totals.get)

    out = [row[:] for row in grid]
    for i, a in enumerate(patches):
        color, ar0, ar1, ac0, ac1, _ = a
        if color == ordinary:
            continue
        for b in patches[i + 1:]:
            color2, br0, br1, bc0, bc1, _ = b
            if color2 != color:
                continue

            # Join horizontally aligned patches through empty cells.
            rlo, rhi = max(ar0, br0), min(ar1, br1)
            if rlo <= rhi and (ac1 < bc0 or bc1 < ac0):
                left, right = (ac1, bc0) if ac1 < bc0 else (bc1, ac0)
                for r in range(rlo, rhi + 1):
                    for c in range(left + 1, right):
                        if out[r][c] == 0:
                            out[r][c] = color

            # Join vertically aligned patches through empty cells.
            clo, chi = max(ac0, bc0), min(ac1, bc1)
            if clo <= chi and (ar1 < br0 or br1 < ar0):
                top, bottom = (ar1, br0) if ar1 < br0 else (br1, ar0)
                for c in range(clo, chi + 1):
                    for r in range(top + 1, bottom):
                        if out[r][c] == 0:
                            out[r][c] = color
    return out
